const { withGradleProperties } = require("expo/config-plugins");

/**
 * Android 8 (API 26) is the floor, decided on 2026-10-18 for Health Connect (W-04): its client
 * supports nothing older. React Native's own default is 24.
 *
 * A gradle property rather than an edit: `android/` is regenerated by prebuild, and Expo's settings
 * plugin reads `android.minSdkVersion` into the `minSdk` every module builds against.
 */
const MIN_SDK = "26";

module.exports = function withAndroidMinSdk(config) {
  return withGradleProperties(config, (cfg) => {
    cfg.modResults = cfg.modResults.filter(
      (item) => !(item.type === "property" && item.key === "android.minSdkVersion"),
    );
    cfg.modResults.push({ type: "property", key: "android.minSdkVersion", value: MIN_SDK });
    return cfg;
  });
};
